import{_ as d}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as c,a as m,b as h,c as g,d as u,e as b,f as y,g as s,h as f,i as n,j as r,k as x,l as w,m as v,n as k,o as l,p as F,q as _,r as z,s as S,t as q,u as D,v as A,w as t,x as B,y as P,z as C,A as T,B as E,C as N,D as I,E as G,F as L,G as R,H as Y,I as U,J as M,K as H}from"./chunks/M-S-DS6aa7.CdBISpqM.js";import{_ as O}from"./chunks/M-S-DS2l2.BdmWUi3X.js";import{_ as W}from"./chunks/M-S-SW8c.OZF8VB_x.js";import{_ as p}from"./chunks/OFF.BrU7kQE-.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as a}from"./chunks/DIS.DdpTdGGD.js";import{_ as $}from"./chunks/M-S-PS5b.B4zocwby.js";import{_ as V,o as j,c as J,a3 as K}from"./chunks/framework.g9mfNVRQ.js";const ga=JSON.parse('{"title":"Display","description":"","frontmatter":{},"headers":[],"relativePath":"use/display.md","filePath":"use/display.md"}'),Q={name:"use/display.md"};function X(Z,o,aa,ia,ea,ta){return j(),J("div",null,[...o[0]||(o[0]=[K('<div class="admonition xdrip"><p class="admonition-title"><img src="'+d+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Display</p></div><p>This menu allows you to customize many visual aspect settings of xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Display</p><p> Display customizations</p></div><p><em>Note: Check <a href="#graph-settings">Graph settings</a> features before using Color settings.</em></p><h3 id="color-settings" tabindex="-1">Color Settings <a class="header-anchor" href="#color-settings" aria-label="Permalink to &quot;Color Settings&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Color settings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_palette_grey600_48dp.png" style="width:8%;"> Customize Colors</p></div><p>The example chart on top will show the effect of what you modify.</p><div class="admonition xdripitem"><p class="admonition-title">Example graph</p><p> <img src="'+c+'" style="zoom:75%;"></p></div><p>When modifying a color you can choose</p><ol><li>hue and saturation</li><li>lightness/darkness</li><li>transparency.</li></ol><p>The result will show compared to the original color.</p><p>You can revert the color to default or save it.</p><img src="'+m+'" style="zoom:75%;"><h5 id="glucose-values-and-lines" tabindex="-1">Glucose values and lines <a class="header-anchor" href="#glucose-values-and-lines" aria-label="Permalink to &quot;Glucose values and lines&quot;">​</a></h5><p>You can customize the main BG plot. High and Low limits are defined in <a href="./settings.html#glucose-units">Glucose Units settings.</a></p><p>High, In-range and Low Values color will change the graph and limit lines on your main view, notification and widget charts.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>READING DOTS</small></small></p><p>High<span style="float:right;width:40px;height:40px;background-color:#FFBB33;display:inline-block;"></span></p><p>In-range<span style="float:right;width:40px;height:40px;background-color:#33B5E6;display:inline-block;"></span></p><p>Low<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p><p>Bad<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Filtered<span style="float:right;width:40px;height:40px;background-color:#A0A0A0;display:inline-block;"></span></p></div><img src="'+h+'" style="zoom:75%;"><p>Bad and filtered values can be seen with sensors supporting raw data.</p><img src="'+g+'" style="zoom:75%;"><h5 id="colors-of-bg-readings-and-trend-arrows" tabindex="-1">Colors of BG readings and Trend Arrows <a class="header-anchor" href="#colors-of-bg-readings-and-trend-arrows" aria-label="Permalink to &quot;Colors of BG readings and Trend Arrows&quot;">​</a></h5><p>You can also customize the current BG value and trend arrow color with respect to range limits.</p><img src="'+u+'" style="zoom:75%;"><div class="admonition xdrip"><p class="admonition-title"><small><small>FONTS</small></small></p><p>High<span style="float:right;width:40px;height:40px;background-color:#FFBB33;display:inline-block;"></span></p><p>In-range<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Low<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p><p>Forecasted low (critical)<span style="float:right;width:40px;height:40px;background-color:#C30909;display:inline-block;"></span></p></div><p>Forecasted low (critical) is the color of the forecasted low message on the main screen when the low is close.</p><h5 id="treatments-and-predictions-curves" tabindex="-1">Treatments and predictions curves <a class="header-anchor" href="#treatments-and-predictions-curves" aria-label="Permalink to &quot;Treatments and predictions curves&quot;">​</a></h5><ol><li>Insulin on board (<a href="./mainUI.html#units-of-insulin">treatment</a> main curve)</li><li>Insulin activity (small dotted line)</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>TREATMENTS / PREDICTION CURVES</small></small></p><p>Insulin on Board<span style="float:right;width:40px;height:40px;background-color:#77AA00;display:inline-block;"></span></p><p>Insulin Activity<span style="float:right;width:40px;height:40px;background-color:#334400;display:inline-block;"></span></p></div><img src="'+b+'" style="zoom:75%;"><ol><li>Glucose <a href="./predictions.html">prediction</a> (main prediction graph)</li><li><a href="./mainUI.html#grams-of-carbs">Carbs</a> on board (small dotted line)</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>TREATMENTS / PREDICTION CURVES</small></small></p><p>Glucose Prediction<span style="float:right;width:40px;height:40px;background-color:#AA66CC;display:inline-block;"></span></p><p>Carbs on Board<span style="float:right;width:40px;height:40px;background-color:#7700AA;display:inline-block;"></span></p></div><img src="'+y+'" style="zoom:75%;"><h5 id="average-and-target-lines" tabindex="-1">Average and target lines <a class="header-anchor" href="#average-and-target-lines" aria-label="Permalink to &quot;Average and target lines&quot;">​</a></h5><ol><li>8-Hour average line</li><li>24-Hour average line</li><li>Target line</li></ol><div class="admonition xdrip"><p class="admonition-title"><small><small>AVERAGE AND TARGET LINES</small></small></p><p>8-hour average<span style="float:right;width:40px;height:40px;background-color:#558800;display:inline-block;"></span></p><p>24-hour average<span style="float:right;width:40px;height:40px;background-color:#C56F9D;display:inline-block;"></span></p><p>Target<span style="float:right;width:40px;height:40px;background-color:#A4A409;display:inline-block;"></span></p></div><img src="'+s+'" style="zoom:75%;"><h5 id="annotations-and-dots" tabindex="-1">Annotations and dots <a class="header-anchor" href="#annotations-and-dots" aria-label="Permalink to &quot;Annotations and dots&quot;">​</a></h5><p><a href="./mainUI.html#treatments">Blood tests (also calibrations), and treatments.</a></p><div class="admonition xdrip"><p class="admonition-title"><small><small>ANNOTATIONS AND DOTS</small></small></p><p>Blood test background<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Blood test dot<span style="float:right;width:40px;height:40px;background-color:#FF4444;display:inline-block;"></span></p><p>Treatment background<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Treatment dot<span style="float:right;width:40px;height:40px;background-color:#77AA00;display:inline-block;"></span></p></div><h5 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h5><img src="'+f+'" style="zoom:75%;"><h5 id="backgrounds" tabindex="-1">Backgrounds <a class="header-anchor" href="#backgrounds" aria-label="Permalink to &quot;Backgrounds&quot;">​</a></h5><p>Graph backgrounds, main chart</p><div class="admonition xdrip"><p class="admonition-title"><small><small>BACKGROUNDS</small></small></p><p>Main graph <span style="float:right;width:40px;height:40px;background-color:#212121;border:1px solid #FFFFFF;display:inline-block;"></span></p><p>Notification graph <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#FFFFFF;background-image:linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888), linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Widget <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#4C4C4C;background-image:linear-gradient(45deg, #333 25%, transparent 25%, transparent 75%, #333 75%, #333), linear-gradient(45deg, #333 25%, transparent 25%, transparent 75%, #333 75%, #333);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><p>Example: notification chart background</p><img src="'+n+'" style="zoom:75%;"><h5 id="plugins-and-features" tabindex="-1">Plugins and features <a class="header-anchor" href="#plugins-and-features" aria-label="Permalink to &quot;Plugins and features&quot;">​</a></h5><p>If you use a <a href="./../calibrate/advancedcal.html#plugins">plugin</a> you can also display the plugin glucose value as a secondary graph.<br> Plugin plot on graph must be enabled.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>PLUGINS AND FEATURES</small></small></p><p>Secondary plugin value <span style="float:right;width:40px;height:40px;background-color:#292A2B;border:1px solid #FFFFFF;display:inline-block;"></span></p></div><img src="'+O+'" style="zoom:75%;"><p>If you have steps and heart rate from a <a href="./../smartwatch/smartwatch.html#smartwatch-sensors">wearable device</a> you can customize graph colors.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>PLUGINS AND FEATURES</small></small></p><p>Step counter 1st color <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#CBE5DF;background-image:linear-gradient(45deg, #6B857F 25%, transparent 25%, transparent 75%, #6B857F 75%, #6B857F), linear-gradient(45deg, #6B857F 25%, transparent 25%, transparent 75%, #6B857F 75%, #6B857F);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Step counter 2nd color <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#DEF1F0;background-image:linear-gradient(45deg, #7D908F 25%, transparent 25%, transparent 75%, #7D908F 75%, #7D908F), linear-gradient(45deg, #7D908F 25%, transparent 25%, transparent 75%, #7D908F 75%, #7D908F);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Heart rate monitor <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#DADCF9;background-image:linear-gradient(45deg, #707290 25%, transparent 25%, transparent 75%, #707290 75%, #707290), linear-gradient(45deg, #707290 25%, transparent 25%, transparent 75%, #707290 75%, #707290);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><p>In the example below 1. heart rate and 2. step counter.</p><img src="'+W+'" style="zoom:75%;"><h5 id="basal-and-smb" tabindex="-1">Basal and SMB <a class="header-anchor" href="#basal-and-smb" aria-label="Permalink to &quot;Basal and SMB&quot;">​</a></h5><p>If you manage to display basal (<a href="#basal-information">from AAPS</a> or <a href="./predictions.html#basal-profile-editor">manual setup</a>) you can also customize the color.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>INSULIN</small></small></p><p>Basal TBR <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#558AE4;background-image:linear-gradient(45deg, #3F74CE 25%, transparent 25%, transparent 75%, #3F74CE 75%, #3F74CE), linear-gradient(45deg, #3F74CE 25%, transparent 25%, transparent 75%, #3F74CE 75%, #3F74CE);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>SMB Icon <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#E4DF63;background-image:linear-gradient(45deg, #CEC94D 25%, transparent 25%, transparent 75%, #CEC94D 75%, #CEC94D), linear-gradient(45deg, #CEC94D 25%, transparent 25%, transparent 75%, #CEC94D 75%, #CEC94D);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>SMB Line <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#7494D4;background-image:linear-gradient(45deg, #5F7FC0 25%, transparent 25%, transparent 75%, #5F7FC0 75%, #5F7FC0), linear-gradient(45deg, #5F7FC0 25%, transparent 25%, transparent 75%, #5F7FC0 75%, #5F7FC0);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p></div><img src="'+r+'" style="zoom:75%;"><p><a href="#smb">SMB</a>s are icons decluttering the graph for micro-bolus treatments.</p><img src="'+x+'" style="zoom:75%;"><h5 id="flair-colors" tabindex="-1">Flair colors <a class="header-anchor" href="#flair-colors" aria-label="Permalink to &quot;Flair colors&quot;">​</a></h5><p>If you want to put some color on the top and bottom bars of your Android screen, enable flair colors.</p><div class="admonition xdrip"><p class="admonition-title"><small><small>FLAIR</small></small></p><p>Custom Title/Nav Bar <span style="float:right;"><img src="'+p+'" style="zoom:75%;"></span></p><p>Upper Title Bar <span style="float:right;display:inline-block;width:40px;height:40px;background-color:#FFFFFF;background-image:linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888), linear-gradient(45deg, #888 25%, transparent 25%, transparent 75%, #888 75%, #888);background-size:20px 20px;background-position:0 0, 10px 10px;border:1px solid #000;"></span></p><p>Lower Navigation Bar <span style="float:right;width:40px;height:40px;background-color:#000000;border:1px solid #FFFFFF;display:inline-block;"></span></p></div><p>Upper title bar:</p><img src="'+w+'" style="zoom:75%;"><p>Lower navigation bar:</p><img src="'+v+'" style="zoom:75%;"><h3 id="font-settings" tabindex="-1">Font Settings <a class="header-anchor" href="#font-settings" aria-label="Permalink to &quot;Font Settings&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Font Settings</p><p> Customize Fonts</p></div><div class="admonition xdripitem"><p class="admonition-title">Enlarge fonts on larger displays<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Automatically enlarge the font size on large screens, such as tablets</p></div><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p>By default xDrip will use your phone language. You can select another language for xDrip and force it to display instead of the phone language.</p><p>For this:</p><p>Select the language in Choose a specific language.</p><div class="admonition xdripitem"><p class="admonition-title">Choose a specific language</p></div><img src="'+k+'" style="zoom:75%;"><p>Toggle the Force English Text switch to ON.</p><div class="admonition xdripitem"><p class="admonition-title">Force English Text<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><h3 id="smooth-sensor-noise" tabindex="-1">Smooth sensor noise <a class="header-anchor" href="#smooth-sensor-noise" aria-label="Permalink to &quot;Smooth sensor noise&quot;">​</a></h3><p>Smoothing displays the smoothed curve (it does not change readings), useful for noisy measurements.<br> You can also try <a href="#graph-smoothing">Graph smoothing</a> to clean your graph.</p><div class="admonition xdripitem"><p class="admonition-title">⚠ Smooth sensor noise<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Try to work around noisy readings</p></div><img src="'+l+'" style="zoom:75%;"><h3 id="show-interface-hints" tabindex="-1">Show interface hints <a class="header-anchor" href="#show-interface-hints" aria-label="Permalink to &quot;Show interface hints&quot;">​</a></h3><p>After you first install xDrip you will see hints during first opening of some features, you can disable this behavior or reset it.</p><div class="admonition xdripitem"><p class="admonition-title">Show interface hints<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Show tips / hints describing button functions etc. Uncheck and Recheck to reset to the beginning</p></div><img src="'+F+'" style="zoom:75%;"><h3 id="graph-settings" tabindex="-1">Graph Settings <a class="header-anchor" href="#graph-settings" aria-label="Permalink to &quot;Graph Settings&quot;">​</a></h3><p>You can customize most of the items that will display on the main graph.</p><div class="admonition xdripitem"><p class="admonition-title">Graph Settings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:8%;"> Adjust chart items</p></div><h5 id="graph-smoothing" tabindex="-1">Graph smoothing <a class="header-anchor" href="#graph-smoothing" aria-label="Permalink to &quot;Graph smoothing&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Graph Smoothing</p></div><p>Graph smoothing will apply a smoothing filter to the graph to make it easier to follow (less noise).</p><p>This is only a visual effect and doesn&#39;t impact readings.</p><div class="admonition xdripitem"><p class="admonition-title">Enable <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Simplify graphs by smoothing out irregularities in the previous readings. The current reading, alerts and broadcast value are not affected by this setting.</p></div><img src="'+_+'" style="zoom:76%;"><img src="'+z+'" style="zoom:76%;"><div class="admonition xdripitem"><p class="admonition-title">Show unsmoothed <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p>Show unsmoothed data also if Graph Smoothing is enabled. If calibration plugin is used, will show unsmoothed data instead of plugin data.</p></div><h5 id="rewrite-history" tabindex="-1">Rewrite history <a class="header-anchor" href="#rewrite-history" aria-label="Permalink to &quot;Rewrite history&quot;">​</a></h5><p>Rewrite history will soften transitions after adding a new calibration to reduce the step-like effect.<br> Make sure this is also enabled on followers to avoid different visualization of past BG values.</p><div class="admonition xdripitem"><p class="admonition-title">Rewrite History <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> After calibration, adjust recent raw graph to smooth to the new calibration</p></div><img src="'+S+'" style="zoom:75%;"><h5 id="widget-range-lines" tabindex="-1">Widget range lines <a class="header-anchor" href="#widget-range-lines" aria-label="Permalink to &quot;Widget range lines&quot;">​</a></h5><p>You can select to visualize high and low limit lines on the widget.</p><div class="admonition xdripitem"><p class="admonition-title">Widget Range Lines <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show a high and low line on the widget</p></div><img src="'+q+'" style="zoom:75%;"><h5 id="main-graph-lines" tabindex="-1">Main graph lines <a class="header-anchor" href="#main-graph-lines" aria-label="Permalink to &quot;Main graph lines&quot;">​</a></h5><p>You can disable vertical time lines on the main graph.</p><div class="admonition xdripitem"><p class="admonition-title">Show Graph grid time lines <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Grid time lines visible</p></div><img src="'+D+'" style="zoom:75%;"><p>You can disable horizontal glucose lines on the main graph.</p><div class="admonition xdripitem"><p class="admonition-title">Show Graph grid glucose lines <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Grid glucose lines visible</p></div><img src="'+A+'" style="zoom:75%;"><h5 id="filtered-data" tabindex="-1">Filtered data <a class="header-anchor" href="#filtered-data" aria-label="Permalink to &quot;Filtered data&quot;">​</a></h5><p>Filtered or smoothed plot adds another graph curve and can optionally create missing data.</p><div class="admonition xdripitem"><p class="admonition-title">Display Filtered Plot <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Useful for noise and missed readings</p></div><div class="admonition xdripitem"><p class="admonition-title">Create missing filtered <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Make filtered data as needed</p></div><img src="'+l+'" style="zoom:75%;"><p>For some data sources (like patched LL app) this will expose the unfiltered raw data as xDrip BG display is already filtered.</p><img src="'+t+'" style="zoom:75%;"><h5 id="raw-data" tabindex="-1">Raw data <a class="header-anchor" href="#raw-data" aria-label="Permalink to &quot;Raw data&quot;">​</a></h5><p>Raw data that can be displayed by xDrip if available.</p><div class="admonition xdripitem"><p class="admonition-title">Display raw data plot <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>G4, G5 and rebatteried G6 provide raw data.</p><img src="'+B+'" style="zoom:75%;"><p>Now raw data are mainly visible for Libre sensors but not with this option.<br> For Libre sensor raw data use <a href="./lesscommon.html#advanced-settings-for-libre-2">Advanced Settings for Libre 2</a>.</p><h5 id="basal-information" tabindex="-1">Basal information <a class="header-anchor" href="#basal-information" aria-label="Permalink to &quot;Basal information&quot;">​</a></h5><p>If basal information is available from an external source (<a href="https://androidaps.readthedocs.io/en/latest/index.html" target="_blank" rel="noreferrer">AAPS NSClient</a>) it can be displayed by xDrip.</p><p>In AAPS/NSClient:</p><ul><li><p>Config builder</p></li><li><p>Synchronization - xDrip settings</p></li><li><p>Enable Send status line to xDrip</p></li></ul><img src="'+P+'" style="zoom:75%;"><p>In xDrip:</p><ul><li>Settings - Less common settings - Enable Extra status line - Enable <a href="./lesscommon.html#extra-status-line">External status</a></li><li>Settings - Inter-app - Enable <a href="./interapp.html#receiving-from-nsclient">Accept treatments</a></li><li>Enable Show basal TBR</li></ul><div class="admonition xdripitem"><p class="admonition-title">Show Basal TBR <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+r+'" style="zoom:75%;"><p>Basal information will also be uploaded to <a href="./cloud.html#tidepool">Tidepool</a>.</p><h5 id="target-and-average-lines" tabindex="-1">Target and average lines <a class="header-anchor" href="#target-and-average-lines" aria-label="Permalink to &quot;Target and average lines&quot;">​</a></h5><p>You can visualize various reference lines on the graph:</p><div class="admonition xdripitem"><p class="admonition-title">Show Graph target line <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Show Graph recent average <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Show Graph total average <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><ol><li>8-Hour average line (recent)</li><li>24-Hour average line (total)</li><li><a href="./predictions.html#low-level-prediction">Target</a> line</li></ol><img src="'+s+'" style="zoom:75%;"><h5 id="libre-trend" tabindex="-1">Libre trend <a class="header-anchor" href="#libre-trend" aria-label="Permalink to &quot;Libre trend&quot;">​</a></h5><p><a href="./3dotsmenu.html#libre-trend">Libre trend</a> enables a small graph available in the three dots menu on the main view.</p><div class="admonition xdripitem"><p class="admonition-title">Show Libre trend <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><h5 id="g6-predictions" tabindex="-1">G6 predictions <a class="header-anchor" href="#g6-predictions" aria-label="Permalink to &quot;G6 predictions&quot;">​</a></h5><p>Dex Prediction is a built-in feature of the Dexcom G6 transmitter showing as small grey dots.</p><div class="admonition xdripitem"><p class="admonition-title">Dex Prediction <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show Dex predictive glucose dots</p></div><img src="'+C+'" style="zoom:75%;"><h5 id="smb" tabindex="-1">SMB <a class="header-anchor" href="#smb" aria-label="Permalink to &quot;SMB&quot;">​</a></h5><p>SMBs are icons decluttering the graph for micro-bolus treatments. Touching the SMB gives the amount of insulin in the information line.</p><div class="admonition xdripitem"><p class="admonition-title">Show micro bolus icons <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><img src="'+T+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Medtrum Secondary <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Display the Medtrum A6 secondary sensor values.</p><h5 id="trend-momentum" tabindex="-1">Trend momentum <a class="header-anchor" href="#trend-momentum" aria-label="Permalink to &quot;Trend momentum&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Show momentum working curve <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Displays a red dotted line (1) momentum extrapolating current BG trend for predicted lows/highs.<br> It is completely independent from <a href="./predictions.html#use-trend-momentum">predictions</a> (2) and doesn&#39;t take into consideration carbs or insulin models.</p><img src="'+$+'" style="zoom:75%;"><h5 id="noise-workings" tabindex="-1">Noise workings <a class="header-anchor" href="#noise-workings" aria-label="Permalink to &quot;Noise workings&quot;">​</a></h5><p>Additional noise calculation visual information, five dots yellow line on the right of the curve.</p><div class="admonition xdripitem"><p class="admonition-title">Show Noise workings <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+t+'" style="zoom:75%;"><h5 id="backfilled-data" tabindex="-1">Backfilled data <a class="header-anchor" href="#backfilled-data" aria-label="Permalink to &quot;Backfilled data&quot;">​</a></h5><p>Backfilled data can be indicated with an empty blue dot.</p><div class="admonition xdripitem"><p class="admonition-title">Show backfilled data <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+E+'" style="zoom:75%;"><h5 id="widget-graph" tabindex="-1">Widget graph <a class="header-anchor" href="#widget-graph" aria-label="Permalink to &quot;Widget graph&quot;">​</a></h5><p>You can hide the graph on the <a href="./mainUI.html#widget">widget</a> and keep only the value.</p><div class="admonition xdripitem"><p class="admonition-title">Hide widget graph <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+N+'" style="zoom:75%;"><p>These two options are only available for developers.</p><div class="admonition xdripitem"><p class="admonition-title">Illustrate remote data <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><h5 id="y-axis" tabindex="-1">Y-axis <a class="header-anchor" href="#y-axis" aria-label="Permalink to &quot;Y-axis&quot;">​</a></h5><p>The main screen vertical axis has a default minimum of 40 mg/dl (2.22 mmol/l) and default maximum of 250 mg/dl (13.9 mmol/l).</p><p>You can arbitrarily fix the lower and upper values for the Y axis.</p><div class="admonition xdripitem"><p class="admonition-title">Customize Y-axis range</p></div><p>By default, whenever readings are out of this range, the graph will temporarily extend the range to make them visible, then return to your fixed values once those readings scroll off.</p><p>If you&#39;d rather keep the Y-axis range fixed and pan the graph vertically instead of expanding it, enable Auto-pan.</p><div class="admonition xdripitem"><p class="admonition-title">Auto-pan Y-axis <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> <strong>Enable:</strong> Pan the graph with a fixed Y-axis range (minimum–maximum) to show out-of-range readings.<br>  <strong>Disable:</strong> Expand the Y-axis range to include out-of-range readings.</p></div><h3 id="glucose-number-from-filtered" tabindex="-1">Glucose number from Filtered <a class="header-anchor" href="#glucose-number-from-filtered" aria-label="Permalink to &quot;Glucose number from Filtered&quot;">​</a></h3><p>Filtering might delay readings and is not recommended.<br> Filtering is hardware coded for <a href="./../install/libre2patch.html">Patched Libre 2 app data source</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Glucose number from filtered <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+t+'" style="zoom:75%;"><h3 id="bolus-wizard-preview" tabindex="-1">Bolus Wizard Preview <a class="header-anchor" href="#bolus-wizard-preview" aria-label="Permalink to &quot;Bolus Wizard Preview&quot;">​</a></h3><p>BWP will show insulin on board (IoB) and suggest corrections based on the <a href="./predictions.html">predictive</a> parameters entered in xDrip.<br> This is an indication. Make sure you understand the EULA before using it.<br> Never follow the suggestions when BG is changing fast.</p><p>Bolus Wizard Preview will show only when either carbs or insulin are present.</p><div class="admonition xdripitem"><p class="admonition-title">Show Bolus Wizard Preview <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Display Insulin/Carb calculations</p></div><img src="'+I+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Always show Bolus Wizard Preview <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Display Insulin/Carb calculations at all times</p></div><p>If you force always show BWP it will always suggest a correction (insulin or carbs).</p><img src="'+G+'" style="zoom:75%;"><h3 id="high-priority-notifications" tabindex="-1">High Priority Notifications <a class="header-anchor" href="#high-priority-notifications" aria-label="Permalink to &quot;High Priority Notifications&quot;">​</a></h3><p>This will bring xDrip <a href="./misc.html#run-collector-in-foreground">graph and notifications</a> to the top of the list, disabling it brings it down.</p><p>You can disable High Priority Notifications if you&#39;d rather have xDrip lower in the notifications list. The <a href="./misc.html#run-collector-in-foreground">collector always runs in foreground</a> on Android 8.0 and above, so xDrip won&#39;t be put to sleep by Android.</p><div class="admonition xdripitem"><p class="admonition-title">High Priority Notifications<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Show notifications and graph at the top (also useful on lockscreen)</p></div><img src="'+n+'" style="zoom:75%;"><h3 id="public-notifications" tabindex="-1">Public Notifications <a class="header-anchor" href="#public-notifications" aria-label="Permalink to &quot;Public Notifications&quot;">​</a></h3><p>This makes notifications visible on the locked screen.</p><div class="admonition xdripitem"><p class="admonition-title">Public Notifications <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><h3 id="enable-reminder-features" tabindex="-1">Enable Reminder Features <a class="header-anchor" href="#enable-reminder-features" aria-label="Permalink to &quot;Enable Reminder Features&quot;">​</a></h3><p>Enabled by default, you&#39;ll find reminders in the <a href="./3dotsmenu.html">three dots menu</a> top right on the main view.</p><div class="admonition xdripitem"><p class="admonition-title">Enable Reminder Features <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Show reminder menus and features</p></div><h3 id="always-on-display-settings" tabindex="-1">Always On Display Settings <a class="header-anchor" href="#always-on-display-settings" aria-label="Permalink to &quot;Always On Display Settings&quot;">​</a></h3><p>xDrip can use Android accessibility to display its widget in the always on display screen, if your phone supports it.</p><div class="admonition xdripitem"><p class="admonition-title">Enable xDrip Accessibility</p><p> If your phone has Always On Display you can enable the xDrip widget there by enabling the xDrip accessibility service from the Android System Settings page.</p></div><img src="'+L+'" style="zoom:75%;"><img src="'+R+'" style="zoom:75%;"><p>On Android 16 and above, you can alternatively show your glucose as a notification chip on the lock screen / always on display, using the ongoing persistent notification instead of accessibility. This relies on <a href="./alarms.html#notification-channels">Notification Channels</a>, which are always active on Android 8.0 and above.</p><div class="admonition xdripitem"><p class="admonition-title">Use AOD chip style <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Display notification chip and lockscreen notification. Android 16+ only</p></div><h3 id="numbered-wall-on-locked-screen" tabindex="-1">Numbered wall on Locked Screen <a class="header-anchor" href="#numbered-wall-on-locked-screen" aria-label="Permalink to &quot;Numbered wall on Locked Screen&quot;">​</a></h3><p>xDrip can display your BG value on the phone locked screen.</p><div class="admonition xdripitem"><p class="admonition-title">Number wall on lock screen</p></div><p>This menu allows you to customize the number displayed.</p><div class="admonition xdripitem"><p class="admonition-title">Configure Number wall</p><p>Adjust and preview wall layout</p></div><p>You will see a real time preview of the result (123 ⇅)</p><ol><li>Change the font size</li><li>Change the vertical position (or vertical distance between numbers)</li><li>Change the horizontal position (or horizontal distance between numbers)</li><li>Change the number color</li><li>Select the background image</li><li>The actual numbered wall</li></ol><img src="'+Y+'" style="zoom:75%;"><p>Enable Locked screen display to show the numbered wall.</p><div class="admonition xdripitem"><p class="admonition-title">Use on Lock screen<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Show number wall on lock screen when enabled</p></div><p>By default the number wall on the lock screen uses the same low/in-range/high glucose colors as the main screen. You can force it to always use a single fixed color instead.</p><div class="admonition xdripitem"><p class="admonition-title">Force text color<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Enable: Always use the selected text color.<br>  Disable: Use main screen glucose colors (low / in-range / high).</p></div><div class="admonition xdrip"><p class="admonition-title">Number Wall on Lock Screen</p><p>Text color<span style="float:right;width:40px;height:40px;background-color:#FFFFFF;display:inline-block;"></span></p><p>Text shadow color<span style="float:right;width:40px;height:40px;background-color:#000000;display:inline-block;"></span></p></div><p>Enable and disable the feature for a defined period of the day. By default it is enabled all day long.</p><div class="admonition xdripitem"><p class="admonition-title">Start time</p><p>Choose number wall start time (same as end for all day)</p></div><div class="admonition xdripitem"><p class="admonition-title">End time</p><p>Choose number wall end time (same as start for all day)</p></div><h3 id="number-icon-in-notification-area" tabindex="-1">Number Icon in Notification Area <a class="header-anchor" href="#number-icon-in-notification-area" aria-label="Permalink to &quot;Number Icon in Notification Area&quot;">​</a></h3><p>xDrip can display your BG number as an icon in the top left notification area and in the drop down notifications.</p><img src="'+U+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Number Icon in Notification Area</p></div><p><strong>You should test the feature before using it as it might crash on some phones.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Run Number Icon Test</p><p> Number icons crash some phones! Tap to run the test before enabling the feature!</p></div><img src="'+M+'" style="zoom:75%;"><p>Your phone will vibrate a few times during the test and you should see the BG icon 123 top left.</p><img src="'+H+'" style="zoom:75%;"><p>If this doesn&#39;t work it means you shouldn&#39;t enable the feature.</p><p><strong>Once functionality is confirmed</strong> you can enable it.</p><div class="admonition xdripitem"><p class="admonition-title">Number Icon tested<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> When you have confirmed your device can display a number icon</p></div><div class="admonition xdripitem"><p class="admonition-title">Show Small Number Icon<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Shows the current glucose number as an icon for the notification bar and lock screen</p></div><h3 id="show-xdrip-on-boot" tabindex="-1">Show xDrip on Boot <a class="header-anchor" href="#show-xdrip-on-boot" aria-label="Permalink to &quot;Show xDrip on Boot&quot;">​</a></h3><p>This will make xDrip open automatically when your phone restarts.</p><p>It might be a good idea to enable this feature if your phone performs automatic updates and reboots (not recommended) and xDrip is not starting automatically at reboot.</p><div class="admonition xdripitem"><p class="admonition-title">Show xDrip on Boot <span class="symbol"><img src="'+p+'" style="zoom:75%;"></span></p><p> Bring up xDrip screen automatically after device boots</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',245)])])}const ua=V(Q,[["render",X]]);export{ga as __pageData,ua as default};
